css:
/* css/radio.css */
/* MZEED identity: paper #eaeae6, grey #bcbec0, charcoal #0d0e0f */
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #0d0e0f; color: #f4f4f1;
  font-family: "SamsungOneArabic", "Samsung One Arabic", "TizenSans", "Noto Sans Arabic", "Noto Kufi Arabic", Tahoma, Arial, sans-serif;
  -webkit-font-smoothing: antialiased; }
* { box-sizing: border-box; }
#app { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; -webkit-transform-origin: 0 0; transform-origin: 0 0; }
/* background scene: photo + drifting clouds and valley mist that pass BEHIND the mountains
   (fg.webp is the same photo with only the dark rocks kept, laid on top of the mist) */
.scene { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; background: #2a2b2d;
  -webkit-animation: kb 40s ease-in-out infinite alternate; animation: kb 40s ease-in-out infinite alternate; will-change: transform; }
.scene .base, .scene .fg { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
.clouds, .clouds2, .fog { position: absolute; left: 0; background-repeat: repeat-x; will-change: transform; }
.clouds { top: 0; width: 3840px; height: 560px; background-image: url(images/clouds.webp); background-size: 1920px 560px;
  -webkit-animation: drift 70s linear infinite; animation: drift 70s linear infinite; }
.clouds2 { top: 40px; width: 5120px; height: 520px; background-image: url(images/clouds2.webp); background-size: 2560px 520px; opacity: 0.8;
  -webkit-animation: drift2 120s linear infinite; animation: drift2 120s linear infinite; }
.fog { top: 330px; width: 3840px; height: 440px; background-image: url(images/fog.webp); background-size: 1920px 440px;
  -webkit-animation: drift-back 95s linear infinite; animation: drift-back 95s linear infinite; }
/* sunlight breaking through the clouds: a soft glow and slow swaying beams (behind the rocks) */
.sun { position: absolute; left: 820px; top: -260px; width: 800px; height: 800px; border-radius: 50%;
  background: -webkit-radial-gradient(center, circle, rgba(255,255,252,0.7) 0%, rgba(255,255,252,0.22) 35%, rgba(255,255,252,0) 70%);
  background: radial-gradient(circle at center, rgba(255,255,252,0.7) 0%, rgba(255,255,252,0.22) 35%, rgba(255,255,252,0) 70%);
  -webkit-animation: glow 10s ease-in-out infinite alternate; animation: glow 10s ease-in-out infinite alternate; will-change: opacity; }
.rays { position: absolute; left: 520px; top: 60px; width: 1400px; height: 1100px; -webkit-transform-origin: 50% 0; transform-origin: 50% 0;
  background: -webkit-linear-gradient(left, rgba(255,255,255,0) 0%, rgba(255,255,255,0.13) 8%, rgba(255,255,255,0) 15%, rgba(255,255,255,0) 26%, rgba(255,255,255,0.1) 33%, rgba(255,255,255,0) 40%, rgba(255,255,255,0) 52%, rgba(255,255,255,0.14) 58%, rgba(255,255,255,0) 66%, rgba(255,255,255,0) 78%, rgba(255,255,255,0.09) 84%, rgba(255,255,255,0) 92%);
  background: linear-gradient(to right, rgba(255,255,255,0) 0%, rgba(255,255,255,0.13) 8%, rgba(255,255,255,0) 15%, rgba(255,255,255,0) 26%, rgba(255,255,255,0.1) 33%, rgba(255,255,255,0) 40%, rgba(255,255,255,0) 52%, rgba(255,255,255,0.14) 58%, rgba(255,255,255,0) 66%, rgba(255,255,255,0) 78%, rgba(255,255,255,0.09) 84%, rgba(255,255,255,0) 92%);
  -webkit-mask-image: -webkit-linear-gradient(top, #000 0%, rgba(0,0,0,0.6) 45%, rgba(0,0,0,0) 85%);
  mask-image: linear-gradient(to bottom, #000 0%, rgba(0,0,0,0.6) 45%, rgba(0,0,0,0) 85%);
  -webkit-animation: sway 22s ease-in-out infinite alternate; animation: sway 22s ease-in-out infinite alternate; will-change: transform, opacity; }
@-webkit-keyframes glow { from { opacity: 0.45; } to { opacity: 1; } }
@keyframes glow { from { opacity: 0.45; } to { opacity: 1; } }
@-webkit-keyframes sway { from { -webkit-transform: rotate(14deg); opacity: 0.5; } to { -webkit-transform: rotate(24deg); opacity: 1; } }
@keyframes sway { from { transform: rotate(14deg); opacity: 0.5; } to { transform: rotate(24deg); opacity: 1; } }
@-webkit-keyframes drift2 { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(-2560px,0,0); } }
@keyframes drift2 { from { transform: translate3d(0,0,0); } to { transform: translate3d(-2560px,0,0); } }
@-webkit-keyframes drift { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(-1920px,0,0); } }
@keyframes drift { from { transform: translate3d(0,0,0); } to { transform: translate3d(-1920px,0,0); } }
@-webkit-keyframes drift-back { from { -webkit-transform: translate3d(-1920px,0,0); } to { -webkit-transform: translate3d(0,0,0); } }
@keyframes drift-back { from { transform: translate3d(-1920px,0,0); } to { transform: translate3d(0,0,0); } }
@-webkit-keyframes kb { from { -webkit-transform: scale(1) translate3d(0,0,0); } to { -webkit-transform: scale(1.08) translate3d(-24px,-8px,0); } }
@keyframes kb { from { transform: scale(1) translate3d(0,0,0); } to { transform: scale(1.08) translate3d(-24px,-8px,0); } }
.shade { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
  background: -webkit-linear-gradient(top, rgba(13,14,15,0.8) 0%, rgba(13,14,15,0.3) 20%, rgba(13,14,15,0) 36%, rgba(13,14,15,0.3) 50%, rgba(13,14,15,0.85) 70%, rgba(13,14,15,0.97) 100%);
  background: linear-gradient(to bottom, rgba(13,14,15,0.8) 0%, rgba(13,14,15,0.3) 20%, rgba(13,14,15,0) 36%, rgba(13,14,15,0.3) 50%, rgba(13,14,15,0.85) 70%, rgba(13,14,15,0.97) 100%); }
.shadow { text-shadow: 0 3px 16px rgba(0,0,0,0.55), 0 1px 3px rgba(0,0,0,0.45); }

/* MZEED mark (top right) */
.brand { position: absolute; right: 80px; top: 66px; text-align: right; }
.mark { position: relative; width: 401px; height: 84px; margin-left: auto; }
.mark svg { display: block; width: 401px; height: 84px; overflow: visible;
  -webkit-filter: drop-shadow(0 4px 14px rgba(0,0,0,0.45)); filter: drop-shadow(0 4px 14px rgba(0,0,0,0.45));
  -webkit-clip-path: inset(-20px -20px -20px 100%); clip-path: inset(-20px -20px -20px 100%);
  -webkit-animation: write 30s cubic-bezier(.6,0,.2,1) .4s infinite; animation: write 30s cubic-bezier(.6,0,.2,1) .4s infinite; }
.mark .m-body { fill: #d4d5d1; }
/* 30 s cycle: written right-to-left (0-6%), stays, fades out (93-97%), hidden again, repeat */
@-webkit-keyframes write { 0% { -webkit-clip-path: inset(-20px -20px -20px 100%); opacity: 1; } 6%, 93% { -webkit-clip-path: inset(-20px -20px -20px -20px); opacity: 1; }
  97% { -webkit-clip-path: inset(-20px -20px -20px -20px); opacity: 0; } 98% { -webkit-clip-path: inset(-20px -20px -20px 100%); opacity: 0; } 100% { -webkit-clip-path: inset(-20px -20px -20px 100%); opacity: 1; } }
@keyframes write { 0% { clip-path: inset(-20px -20px -20px 100%); opacity: 1; } 6%, 93% { clip-path: inset(-20px -20px -20px -20px); opacity: 1; }
  97% { clip-path: inset(-20px -20px -20px -20px); opacity: 0; } 98% { clip-path: inset(-20px -20px -20px 100%); opacity: 0; } 100% { clip-path: inset(-20px -20px -20px 100%); opacity: 1; } }
.mark .dot { fill: #d4d5d1; opacity: 0; -webkit-transform-box: fill-box; transform-box: fill-box; -webkit-transform-origin: 50% 50%; transform-origin: 50% 50%;
  -webkit-animation: dot 30s linear infinite; animation: dot 30s linear infinite; }
.mark .d1 { -webkit-animation-delay: .4s; animation-delay: .4s; }
.mark .d2 { -webkit-animation-delay: .6s; animation-delay: .6s; }
.mark .d3 { -webkit-animation-delay: .75s; animation-delay: .75s; }
/* the dots drop in just after the writing (~5.7-7.3% of the 30 s cycle) and leave with the mark */
@-webkit-keyframes dot { 0%, 5.6% { opacity: 0; -webkit-transform: translateY(-14px) scale(.4); } 7.3%, 92% { opacity: 1; -webkit-transform: none; } 96%, 100% { opacity: 0; -webkit-transform: none; } }
@keyframes dot { 0%, 5.6% { opacity: 0; transform: translateY(-14px) scale(.4); } 7.3%, 92% { opacity: 1; transform: none; } 96%, 100% { opacity: 0; transform: none; } }
/* light sweep: an SVG gradient that passes over the mark from right to left (twice per 30 s cycle) */
.mark .sheen path { fill: url(#mz-sheen); }
.brand .lockup { display: block; height: 46px; margin: 18px 0 0 auto; opacity: 0;
  -webkit-animation: rise .9s ease-out 2.1s forwards; animation: rise .9s ease-out 2.1s forwards; }
@-webkit-keyframes rise { from { opacity: 0; -webkit-transform: translateY(12px); } to { opacity: .9; -webkit-transform: none; } }
@keyframes rise { from { opacity: 0; transform: translateY(12px); } to { opacity: .9; transform: none; } }

/* clock + dates (top left) */
.hero { position: absolute; left: 80px; top: 54px; text-align: left; }
.time { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; -webkit-justify-content: flex-end; justify-content: flex-end; }
.clock { font-size: 112px; font-weight: 800; line-height: 0.95; letter-spacing: -2px; }
.ampm { font-size: 32px; font-weight: 700; color: #bcbec0; margin: 0 14px 10px 0; }
.date { font-size: 30px; font-weight: 700; margin-top: 12px; }
.hijri { font-size: 26px; font-weight: 700; margin-top: 6px; color: #bcbec0; }
.hint { font-size: 19px; margin-top: 8px; color: rgba(234,234,230,0.5); }
.hint b { color: rgba(234,234,230,0.8); }

/* player card (centre) */
.player { position: absolute; left: 50%; bottom: 310px; width: 960px; margin-left: -480px; height: 204px; padding: 0 44px;
  border-radius: 36px; background: rgba(13,14,15,0.6); border: 2px solid rgba(234,234,230,0.16);
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; box-shadow: 0 24px 60px rgba(0,0,0,0.45); }
.btn { width: 132px; height: 132px; border-radius: 50%; -webkit-flex-shrink: 0; flex-shrink: 0; background: #eaeae6; color: #0d0e0f;
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center;
  box-shadow: 0 12px 34px rgba(0,0,0,0.5); }
.btn svg { width: 70px; height: 70px; fill: currentColor; }
.info { -webkit-flex: 1; flex: 1; margin-right: 40px; }
.status { font-size: 22px; color: #bcbec0; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.live { display: -webkit-inline-flex; display: inline-flex; -webkit-align-items: center; align-items: center; padding: 4px 16px; border-radius: 999px;
  border: 2px solid rgba(234,234,230,0.4); color: #eaeae6; font-size: 21px; font-weight: 800; margin-left: 16px; }
.live:before { content: ""; width: 12px; height: 12px; border-radius: 50%; background: #e5484d; margin-left: 10px; box-shadow: 0 0 10px rgba(229,72,77,0.8); }
.live.off { border-color: rgba(234,234,230,0.2); color: #bcbec0; }
.live.off:before { background: #75777a; box-shadow: none; }
.title { font-size: 42px; font-weight: 800; margin-top: 6px; line-height: 1.25; }
.sub { font-size: 23px; color: #bcbec0; margin-top: 2px; }
.sub b { color: #eaeae6; }
.eq { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; height: 70px; margin-right: 20px; }
.eq i { display: block; width: 10px; margin-left: 7px; border-radius: 5px; background: #eaeae6; height: 14px; opacity: 0.85; }
.playing .eq i { -webkit-animation: eq 1s ease-in-out infinite; animation: eq 1s ease-in-out infinite; }
.playing .eq i:nth-child(2) { -webkit-animation-delay: .2s; animation-delay: .2s; }
.playing .eq i:nth-child(3) { -webkit-animation-delay: .4s; animation-delay: .4s; }
.playing .eq i:nth-child(4) { -webkit-animation-delay: .1s; animation-delay: .1s; }
.playing .eq i:nth-child(5) { -webkit-animation-delay: .3s; animation-delay: .3s; }
@-webkit-keyframes eq { 0%, 100% { height: 14px; } 50% { height: 64px; } }
@keyframes eq { 0%, 100% { height: 14px; } 50% { height: 64px; } }

/* prayer strip */
.city { position: absolute; left: 0; right: 0; bottom: 268px; text-align: center; font-size: 21px; font-weight: 700; color: #bcbec0; }
.prayer { position: absolute; left: 80px; right: 80px; bottom: 154px; height: 100px; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.pr-nx { height: 94px; padding: 10px 26px; border-radius: 20px; margin-left: 14px; background: #eaeae6; color: #0d0e0f; text-align: center; }
.pr-nx small { display: block; font-size: 20px; font-weight: 800; opacity: 0.75; }
.pr-nx b { display: block; font-size: 37px; font-weight: 800; letter-spacing: 1px; }
.pr-it { height: 94px; width: 168px; margin-left: 14px; padding: 10px 0; border-radius: 20px; text-align: center;
  background: rgba(13,14,15,0.55); border: 2px solid rgba(234,234,230,0.12); }
.pr-it small { display: block; font-size: 20px; color: #bcbec0; }
.pr-it b { display: block; font-size: 31px; font-weight: 800; margin-top: 2px; }
.pr-it.next { border-color: #eaeae6; background: rgba(234,234,230,0.12); }
.pr-it.past { opacity: 0.5; }

/* group companies */
.rule { position: absolute; left: 80px; right: 80px; bottom: 100px; height: 2px;
  background: -webkit-linear-gradient(left, rgba(234,234,230,0), rgba(234,234,230,0.28) 12%, rgba(234,234,230,0.28) 88%, rgba(234,234,230,0));
  background: linear-gradient(to right, rgba(234,234,230,0), rgba(234,234,230,0.28) 12%, rgba(234,234,230,0.28) 88%, rgba(234,234,230,0)); }
.group { position: absolute; left: 180px; right: 180px; bottom: 28px; height: 52px; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: space-between; justify-content: space-between; }
/* a wave of light runs across the logos (right to left) every 8 s; the logos themselves stay still */
.group img { display: block; height: 32px; opacity: 0.6; -webkit-animation: wave 8s ease-in-out infinite; animation: wave 8s ease-in-out infinite; }
.group img:nth-child(2) { -webkit-animation-delay: .22s; animation-delay: .22s; }
.group img:nth-child(3) { -webkit-animation-delay: .44s; animation-delay: .44s; }
.group img:nth-child(4) { -webkit-animation-delay: .66s; animation-delay: .66s; }
.group img:nth-child(5) { -webkit-animation-delay: .88s; animation-delay: .88s; }
.group img:nth-child(6) { -webkit-animation-delay: 1.1s; animation-delay: 1.1s; }
.group img:nth-child(7) { -webkit-animation-delay: 1.32s; animation-delay: 1.32s; }
.group img:nth-child(8) { -webkit-animation-delay: 1.54s; animation-delay: 1.54s; }
@-webkit-keyframes wave { 0%, 16%, 100% { opacity: .6; } 7% { opacity: 1; } }
@keyframes wave { 0%, 16%, 100% { opacity: .6; } 7% { opacity: 1; } }
.group .g-fonoon { height: 35px; }
.group .g-moqtana { height: 34px; }
.group .g-mustbee { height: 30px; }
.group .g-ole { height: 29px; }
.group .g-mount { height: 46px; }
.group .g-softimage { height: 35px; }
.group .g-display { height: 29px; }
.group .g-immersive { height: 30px; }

/* ===== option A: radio + prayer times together in one dock ===== */
.dock { position: absolute; left: 80px; right: 80px; bottom: 126px; height: 146px; border-radius: 26px;
  background: rgba(13,14,15,0.62); border: 2px solid rgba(234,234,230,0.14); box-shadow: 0 24px 60px rgba(0,0,0,0.45);
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; padding: 0 36px; }
.dock .player { position: static; margin: 0; left: auto; bottom: auto; width: 560px; height: auto; padding: 0; border: 0; background: none; box-shadow: none; -webkit-flex-shrink: 0; flex-shrink: 0; }
.dock .btn { width: 92px; height: 92px; }
.dock .btn svg { width: 48px; height: 48px; }
.dock .info { margin-right: 24px; }
.dock .status { font-size: 18px; }
.dock .live { font-size: 17px; padding: 2px 12px; }
.dock .live:before { width: 10px; height: 10px; margin-left: 8px; }
.dock .title { font-size: 31px; margin-top: 4px; }
.dock .sub { font-size: 18px; }
.by { font-size: 16px; font-weight: 600; letter-spacing: 0.4px; color: #bcbec0; opacity: 0.85; margin-top: 3px; text-align: right; }
.dock .hint { display: none; }
.dock .eq { height: 46px; margin-right: 8px; }
.dock .eq i { width: 8px; margin-left: 6px; }
.dock .sep { width: 2px; height: 96px; background: rgba(234,234,230,0.14); margin: 0 34px; -webkit-flex-shrink: 0; flex-shrink: 0; }
.dock .times { -webkit-flex: 1; flex: 1; position: relative; height: 108px; }
.dock .city { position: absolute; left: auto; right: 0; top: 0; bottom: auto; text-align: right; font-size: 16px; text-shadow: none; }
.dock .prayer { position: absolute; left: 0; right: 0; top: 26px; bottom: auto; height: 82px; -webkit-justify-content: space-between; justify-content: space-between; }
.dock .pr-it { width: auto; -webkit-flex: 1; flex: 1; height: 78px; margin: 0; padding: 8px 0 0; border: 0; background: none; border-radius: 0; position: relative; }
.dock .pr-it + .pr-it { border-right: 1px solid rgba(234,234,230,0.12); }
.dock .pr-it b { font-size: 26px; white-space: nowrap; }
.dock .pr-it small { white-space: nowrap; font-size: 17px; }
.dock .pr-it.next small, .dock .pr-it.next b { color: #fff; }
.dock .pr-it.next:after { content: ""; position: absolute; left: 30%; right: 30%; bottom: 2px; height: 4px; border-radius: 2px; background: #eaeae6; }
.dock .pr-nx { -webkit-order: 9; order: 9; height: 76px; margin: 0 16px 0 0; padding: 9px 20px; border-radius: 16px; }
.dock .pr-nx small { font-size: 16px; }
.dock .pr-nx b { font-size: 30px; }

/* ===== upcoming exhibitions & conferences (small portrait card, left, under the clock) ===== */
.events { position: absolute; left: 80px; top: 292px; width: 330px; padding: 18px 22px 16px; border-radius: 22px;
  background: rgba(13,14,15,0.58); border: 2px solid rgba(234,234,230,0.14); box-shadow: 0 18px 44px rgba(0,0,0,0.35); }
.ev-head { font-size: 16px; font-weight: 700; color: #bcbec0; line-height: 1.35; }
.ev-head b { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: #eaeae6; margin-left: 8px; vertical-align: middle; }
.ev-body { margin-top: 10px; min-height: 196px; -webkit-transition: opacity .45s ease, -webkit-transform .45s ease; transition: opacity .45s ease, transform .45s ease; }
.ev-body.out { opacity: 0; -webkit-transform: translateY(10px); transform: translateY(10px); }
.ev-name { font-size: 25px; font-weight: 800; line-height: 1.3; max-height: 98px; overflow: hidden; }
.ev-place { font-size: 17px; color: #bcbec0; margin-top: 6px; line-height: 1.4; max-height: 48px; overflow: hidden; }
.ev-place b { color: #d4d5d1; font-weight: 700; }
.ev-date { font-size: 19px; font-weight: 700; color: #eaeae6; margin-top: 8px; }
.ev-row { margin-top: 10px; }
.ev-count { display: inline-block; padding: 3px 13px; border-radius: 999px; background: #eaeae6; color: #0d0e0f; font-size: 17px; font-weight: 800; }
.ev-count.live { background: #e5484d; color: #fff; }
.ev-tag { display: inline-block; margin-right: 8px; padding: 1px 11px; border-radius: 999px; border: 2px solid rgba(234,234,230,0.45); color: #eaeae6; font-size: 15px; font-weight: 700; }
.ev-dots { margin-top: 12px; height: 7px; }
.ev-dots i { display: inline-block; width: 7px; height: 7px; border-radius: 4px; background: rgba(234,234,230,0.3); margin-left: 6px; vertical-align: top;
  -webkit-transition: width .4s, background .4s; transition: width .4s, background .4s; }
.ev-dots i.on { width: 22px; background: #eaeae6; }

/* ===== a soft light runs along the prayer-times frame, the exhibitions frame and the line above the logos (every 8 s, right to left) ===== */
.sheen { position: absolute; left: -2px; top: -2px; right: -2px; bottom: -2px; border-radius: inherit; padding: 2px; overflow: hidden; pointer-events: none;
  -webkit-mask: -webkit-linear-gradient(#000, #000) content-box, -webkit-linear-gradient(#000, #000); -webkit-mask-composite: xor; }
.sheen i, .rule i { position: absolute; left: 0; top: 0; bottom: 0; width: 26%;
  background: -webkit-linear-gradient(left, rgba(255,255,255,0) 0%, rgba(255,255,255,0.7) 50%, rgba(255,255,255,0) 100%);
  background: linear-gradient(to right, rgba(255,255,255,0) 0%, rgba(255,255,255,0.7) 50%, rgba(255,255,255,0) 100%);
  -webkit-transform: translate3d(400%,0,0); transform: translate3d(400%,0,0);
  -webkit-animation: sheen 8s ease-in-out infinite; animation: sheen 8s ease-in-out infinite; will-change: transform; }
.rule { overflow: hidden; }
.rule i { width: 18%; -webkit-animation-name: sheenline; animation-name: sheenline;
  background: -webkit-linear-gradient(left, rgba(255,255,255,0) 0%, rgba(255,255,255,0.9) 50%, rgba(255,255,255,0) 100%);
  background: linear-gradient(to right, rgba(255,255,255,0) 0%, rgba(255,255,255,0.9) 50%, rgba(255,255,255,0) 100%); }
.events .sheen i { -webkit-animation-delay: 2.4s; animation-delay: 2.4s; }
@-webkit-keyframes sheen { 0% { -webkit-transform: translate3d(400%,0,0); } 40%, 100% { -webkit-transform: translate3d(-110%,0,0); } }
@keyframes sheen { 0% { transform: translate3d(400%,0,0); } 40%, 100% { transform: translate3d(-110%,0,0); } }
@-webkit-keyframes sheenline { 0% { -webkit-transform: translate3d(560%,0,0); } 40%, 100% { -webkit-transform: translate3d(-110%,0,0); } }
@keyframes sheenline { 0% { transform: translate3d(560%,0,0); } 40%, 100% { transform: translate3d(-110%,0,0); } }

/* choice of station: Egypt (main) / Saudi Arabia, inside the "live" line */
.stations { display: -webkit-inline-flex; display: inline-flex; vertical-align: middle; margin-left: 10px; }
.st { font-size: 16px; font-weight: 700; padding: 2px 13px; border-radius: 999px; margin-left: 8px; color: #bcbec0;
  background: rgba(234,234,230,0.12); cursor: pointer; }
.st.cur { background: #eaeae6; color: #0d0e0f; }
/* message, version */
#toast { position: absolute; left: 50%; bottom: 300px; -webkit-transform: translateX(-50%); transform: translateX(-50%);
  padding: 14px 30px; border-radius: 16px; background: rgba(13,14,15,0.9); color: #eaeae6; font-size: 26px; font-weight: 700;
  white-space: nowrap; opacity: 0; -webkit-transition: opacity .3s; transition: opacity .3s; pointer-events: none; }
#toast.show { opacity: 1; }
.ver { position: absolute; left: 30px; bottom: 12px; font-size: 15px; color: rgba(234,234,230,0.35); }
.dock .sub { white-space: nowrap; }

