/* ==========================================================================
   saudi-time.js — clock, Gregorian and Hijri (Umm Al-Qura) dates in
   Saudi time (UTC+3, no daylight saving), whatever the TV's own timezone.
   Use the getUTC* methods on the Date returned by now().
   ========================================================================== */
var SaudiTime = (function () {
  var DAYS = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
  var MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  var HMONTHS = ['محرم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'جمادى الأولى', 'جمادى الآخرة',
    'رجب', 'شعبان', 'رمضان', 'شوال', 'ذو القعدة', 'ذو الحجة'];

  function now() { return new Date(new Date().getTime() + 3 * 3600000); }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  /* 12-hour clock text with ص / م */
  function clock12(h, m) {
    var ampm = h < 12 ? 'ص' : 'م';
    var hh = h % 12; if (hh === 0) hh = 12;
    return hh + ':' + pad(m) + ' ' + ampm;
  }

  function parts12(d) {
    var h = d.getUTCHours(), hh = h % 12; if (hh === 0) hh = 12;
    if (api.use24) return { time: pad(h) + ':' + pad(d.getUTCMinutes()), ampm: '' };
    return { time: hh + ':' + pad(d.getUTCMinutes()), ampm: h < 12 ? 'صباحاً' : 'مساءً' };
  }

  /* short clock text that follows the 12/24-hour setting */
  function fmt(h, m) { return api.use24 ? pad(h) + ':' + pad(m) : clock12(h, m); }

  function gregorian(d) {
    return DAYS[d.getUTCDay()] + '، ' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
  }

  /* ---- Hijri: Umm Al-Qura through Intl when the TV supports it ---- */
  var intlFmt = null, intlTried = false;
  function intlHijri(d) {
    if (!intlTried) {
      intlTried = true;
      try {
        var f = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn', { timeZone: 'UTC', day: 'numeric', month: 'numeric', year: 'numeric' });
        if (f.resolvedOptions().calendar === 'islamic-umalqura') intlFmt = f;
      } catch (e) { intlFmt = null; }
    }
    if (!intlFmt) return null;
    try {
      var out = {}, ps = intlFmt.formatToParts(d);
      for (var i = 0; i < ps.length; i++) {
        if (ps[i].type === 'day') out.day = parseInt(ps[i].value, 10);
        if (ps[i].type === 'month') out.month = parseInt(ps[i].value, 10);
        if (ps[i].type === 'year') out.year = parseInt(ps[i].value, 10);
      }
      if (out.day && out.month && out.year) return out;
    } catch (e) {}
    return null;
  }

  /* fallback: tabular Islamic calendar (may differ by a day from Umm Al-Qura) */
  function tabularHijri(d) {
    var jd = Math.floor(d.getTime() / 86400000) + 2440588;     /* civil day number */
    var l = jd - 1948440 + 10632;
    var n = Math.floor((l - 1) / 10631);
    l = l - 10631 * n + 354;
    var j = Math.floor((10985 - l) / 5316) * Math.floor((50 * l) / 17719) + Math.floor(l / 5670) * Math.floor((43 * l) / 15238);
    l = l - Math.floor((30 - j) / 15) * Math.floor((17719 * j) / 50) - Math.floor(j / 16) * Math.floor((15238 * j) / 43) + 29;
    var month = Math.floor((24 * l) / 709);
    var day = l - Math.floor((709 * month) / 24);
    var year = 30 * n + j - 30;
    return { day: day, month: month, year: year };
  }

  /* d is a "Saudi" Date from now(): its UTC fields are Saudi local fields */
  function hijri(d) {
    var noon = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 12));
    return intlHijri(noon) || tabularHijri(noon);
  }

  function hijriText(d) {
    var h = hijri(d);
    return h.day + ' ' + HMONTHS[h.month - 1] + ' ' + h.year + 'هـ';
  }

  var api = { now: now, clock12: clock12, parts12: parts12, fmt: fmt, gregorian: gregorian, hijri: hijri,
    hijriText: hijriText, pad: pad, use24: false, HMONTHS: HMONTHS };
  return api;
})();

/* ==========================================================================
   prayer.js — prayer times calculated on the TV (no internet needed)
   Method: Umm Al-Qura (Saudi Arabia): Fajr 18.5°, Isha = Maghrib + 90 min
   (120 min in Ramadan), Asr standard (shadow = 1). Saudi time = UTC+3.
   Astronomical part follows the well-known PrayTimes.org algorithm.
   ========================================================================== */
var Prayer = (function () {

  var CITIES = [
    { id: 'riyadh', name: 'الرياض', lat: 24.7136, lng: 46.6753 },
    { id: 'makkah', name: 'مكة المكرمة', lat: 21.4225, lng: 39.8262 },
    { id: 'madinah', name: 'المدينة المنورة', lat: 24.4672, lng: 39.6111 },
    { id: 'jeddah', name: 'جدة', lat: 21.4858, lng: 39.1925 },
    { id: 'dammam', name: 'الدمام', lat: 26.4207, lng: 50.0888 },
    { id: 'khobar', name: 'الخبر', lat: 26.2172, lng: 50.1971 },
    { id: 'hofuf', name: 'الأحساء', lat: 25.3833, lng: 49.5856 },
    { id: 'taif', name: 'الطائف', lat: 21.2703, lng: 40.4158 },
    { id: 'buraydah', name: 'بريدة', lat: 26.3592, lng: 43.9818 },
    { id: 'hail', name: 'حائل', lat: 27.5114, lng: 41.7208 },
    { id: 'tabuk', name: 'تبوك', lat: 28.3835, lng: 36.5662 },
    { id: 'abha', name: 'أبها', lat: 18.2465, lng: 42.5117 },
    { id: 'khamis', name: 'خميس مشيط', lat: 18.3000, lng: 42.7333 },
    { id: 'jazan', name: 'جازان', lat: 16.8892, lng: 42.5511 },
    { id: 'najran', name: 'نجران', lat: 17.5656, lng: 44.2289 },
    { id: 'yanbu', name: 'ينبع', lat: 24.0889, lng: 38.0637 },
    { id: 'baha', name: 'الباحة', lat: 20.0129, lng: 41.4677 },
    { id: 'sakaka', name: 'سكاكا', lat: 29.9697, lng: 40.2064 },
    { id: 'arar', name: 'عرعر', lat: 30.9753, lng: 41.0381 }
  ];

  var NAMES = { fajr: 'الفجر', sunrise: 'الشروق', dhuhr: 'الظهر', asr: 'العصر', maghrib: 'المغرب', isha: 'العشاء' };
  var ORDER = ['fajr', 'sunrise', 'dhuhr', 'asr', 'maghrib', 'isha'];
  var TZ = 3;

  /* ---- degree trigonometry ---- */
  function dtr(d) { return d * Math.PI / 180; }
  function rtd(r) { return r * 180 / Math.PI; }
  function sin(d) { return Math.sin(dtr(d)); }
  function cos(d) { return Math.cos(dtr(d)); }
  function tan(d) { return Math.tan(dtr(d)); }
  function arcsin(x) { return rtd(Math.asin(x)); }
  function arccos(x) { return rtd(Math.acos(Math.max(-1, Math.min(1, x)))); }
  function arctan2(y, x) { return rtd(Math.atan2(y, x)); }
  function arccot(x) { return rtd(Math.atan(1 / x)); }
  function fix(a, b) { a = a - b * Math.floor(a / b); return a < 0 ? a + b : a; }

  function julian(y, m, d) {
    if (m <= 2) { y -= 1; m += 12; }
    var A = Math.floor(y / 100), B = 2 - A + Math.floor(A / 4);
    return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + d + B - 1524.5;
  }

  function sunPosition(jd) {
    var D = jd - 2451545.0;
    var g = fix(357.529 + 0.98560028 * D, 360);
    var q = fix(280.459 + 0.98564736 * D, 360);
    var L = fix(q + 1.915 * sin(g) + 0.020 * sin(2 * g), 360);
    var e = 23.439 - 0.00000036 * D;
    var RA = arctan2(cos(e) * sin(L), cos(L)) / 15;
    return { decl: arcsin(sin(e) * sin(L)), eqt: q / 15 - fix(RA, 24) };
  }

  /* times in hours (local Saudi time) for one Gregorian date */
  function compute(city, y, m, d, ramadan) {
    var lat = city.lat, lng = city.lng;
    var jDate = julian(y, m, d) - lng / (15 * 24);
    function midDay(t) { return fix(12 - sunPosition(jDate + t).eqt, 24); }
    function angleTime(angle, t, ccw) {
      var decl = sunPosition(jDate + t).decl, noon = midDay(t);
      var v = arccos((-sin(angle) - sin(decl) * sin(lat)) / (cos(decl) * cos(lat))) / 15;
      return noon + (ccw ? -v : v);
    }
    function asrTime(factor, t) {
      var decl = sunPosition(jDate + t).decl;
      return angleTime(-arccot(factor + tan(Math.abs(lat - decl))), t);
    }
    var t = { fajr: 5, sunrise: 6, dhuhr: 12, asr: 13, sunset: 18 };
    var r = {};
    r.fajr = angleTime(18.5, t.fajr / 24, true);
    r.sunrise = angleTime(0.833, t.sunrise / 24, true);
    r.dhuhr = midDay(t.dhuhr / 24);
    r.asr = asrTime(1, t.asr / 24);
    r.maghrib = angleTime(0.833, t.sunset / 24, false);
    var adj = TZ - lng / 15;
    for (var k in r) if (r.hasOwnProperty(k)) r[k] += adj;
    r.isha = r.maghrib + (ramadan ? 120 : 90) / 60;
    return r;
  }

  function cityById(id) {
    for (var i = 0; i < CITIES.length; i++) if (CITIES[i].id === id) return CITIES[i];
    return CITIES[0];
  }

  /* Today's list for the chosen city, each {key, name, minutes (from Saudi midnight), text} */
  function today(cityId) {
    var city = cityById(cityId);
    var n = SaudiTime.now();
    var ramadan = SaudiTime.hijri(n).month === 9;
    var r = compute(city, n.getUTCFullYear(), n.getUTCMonth() + 1, n.getUTCDate(), ramadan);
    var friday = n.getUTCDay() === 5;
    var list = [];
    for (var i = 0; i < ORDER.length; i++) {
      var k = ORDER[i];
      var mins = Math.round(r[k] * 60);          /* nearest minute */
      list.push({
        key: k,
        name: k === 'dhuhr' && friday ? 'الجمعة' : NAMES[k],
        minutes: mins,
        text: SaudiTime.fmt(Math.floor(mins / 60) % 24, mins % 60)
      });
    }
    return { city: city, list: list };
  }

  /* next prayer (not sunrise) and minutes left; after Isha -> tomorrow's Fajr */
  function next(cityId) {
    var d = today(cityId);
    var n = SaudiTime.now();
    var nowMin = n.getUTCHours() * 60 + n.getUTCMinutes() + n.getUTCSeconds() / 60;
    for (var i = 0; i < d.list.length; i++) {
      var p = d.list[i];
      if (p.key === 'sunrise') continue;
      if (p.minutes > nowMin) return { key: p.key, name: p.name, left: p.minutes - nowMin, today: d };
    }
    var fajr = d.list[0];
    return { key: 'fajr', name: fajr.name, left: fajr.minutes + 1440 - nowMin, today: d, tomorrow: true };
  }

  return {
    CITIES: CITIES, compute: compute, today: today, next: next, cityById: cityById
  };
})();

/* ==========================================================================
   ota.js — updates the app over the internet, no laptop needed.
   The app's own code (page, styles, screens) is downloaded from
   https://mabdullah-apps.github.io/iptv/<platform>/ and kept on the device;
   boot.js starts that newer code the next time the app opens.
   Never part of an update: js/config.js (the private built-in account),
   the saved subscriptions, favourites and settings - those stay on the device.
   ========================================================================== */
var OTA = (function () {
  var BOOT = window.OTA_BOOT || { app: 'iptv', platform: 'tizen', shell: 1, base: '0', running: '0', from: 'package', notes: [] };
  var cfg = window.IPTV_CONFIG || window.RADIO_TEST || {};   /* tests only */
  var BASE_URL = (cfg.otaUrl || 'https://mabdullah-apps.github.io/' + (BOOT.app || 'iptv') + '/') + BOOT.platform + '/';
  var FIRST_CHECK = cfg.otaFirstCheck || 45 * 1000;      /* after the app opens */
  var EVERY = 6 * 3600 * 1000;                            /* then every 6 hours */

  var st = { status: 'idle', latest: null, error: '', checkedAt: 0, busy: false };

  function cmp(a, b) {
    var x = String(a || '0').split('.'), y = String(b || '0').split('.');
    for (var i = 0; i < Math.max(x.length, y.length); i++) {
      var d = (parseInt(x[i], 10) || 0) - (parseInt(y[i], 10) || 0);
      if (d) return d > 0 ? 1 : -1;
    }
    return 0;
  }
  function ls(k, v) {
    try {
      if (v === undefined) return localStorage.getItem(k);
      if (v === null) localStorage.removeItem(k); else localStorage.setItem(k, v);
    } catch (e) {}
    return null;
  }
  function now() { return new Date().getTime(); }

  /* FNV-1a over the text, the same sum the publishing script writes */
  function sum(s) {
    var h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
    }
    return ('0000000' + h.toString(16)).slice(-8);
  }

  function get(url, cb) {
    var x = new XMLHttpRequest(), done = false;
    function end(err, txt) { if (done) return; done = true; cb(err, txt); }
    try {
      x.open('GET', url + (url.indexOf('?') < 0 ? '?' : '&') + 't=' + now(), true);
      x.timeout = 30000;
      x.onload = function () { if (x.status >= 200 && x.status < 300) end(null, x.responseText); else end('http ' + x.status); };
      x.onerror = function () { end('network'); };
      x.ontimeout = function () { end('timeout'); };
      x.send();
    } catch (e) { end('network'); }
  }

  /* the version that is downloaded and will start next time (if newer than the running one) */
  function ready() {
    var v = ls('ota.ready');
    return v && cmp(v, BOOT.running) > 0 && v !== ls('ota.bad') ? v : '';
  }

  function auto() { return ls('ota.auto') !== 'off'; }
  function setAuto(on) { ls('ota.auto', on ? null : 'off'); }

  /* cb({ status: 'latest' | 'ready' | 'needShell' | 'error', version, notes, fresh }) */
  function check(cb) {
    cb = cb || function () {};
    if (st.busy) { cb({ status: 'busy' }); return; }
    st.busy = true;
    get(BASE_URL + 'latest.json', function (err, txt) {
      var L = null;
      if (!err) { try { L = JSON.parse(txt); } catch (e) { err = 'bad file'; } }
      if (err || !L || !L.version) { st.busy = false; st.status = 'error'; st.error = err || 'bad file'; cb({ status: 'error' }); return; }
      st.latest = L;
      st.checkedAt = now();
      var have = ready() || BOOT.running;
      if (cmp(L.version, have) <= 0 || L.version === ls('ota.bad')) {
        st.busy = false;
        st.status = ready() ? 'ready' : 'latest';
        cb({ status: st.status, version: ready() || BOOT.running, notes: readyNotes() });
        return;
      }
      if ((L.minShell || 1) > BOOT.shell) {
        st.busy = false; st.status = 'needShell';
        cb({ status: 'needShell', version: L.version, notes: L.notes || [] });
        return;
      }
      get(BASE_URL + L.bundle, function (err2, txt2) {
        st.busy = false;
        var B = null;
        if (!err2) { try { B = JSON.parse(txt2); } catch (e) { err2 = 'bad file'; } }
        var ok = B && B.version === L.version && B.html && B.css !== undefined && B.js && B.js.length;
        if (ok) {
          var all = B.html + B.css;
          for (var i = 0; i < B.js.length; i++) all += B.js[i].code;
          ok = sum(all) === L.sum;
        }
        if (err2 || !ok) { st.status = 'error'; st.error = err2 || 'damaged download'; cb({ status: 'error' }); return; }
        try {
          localStorage.setItem('ota.bundle', txt2);
        } catch (e) {
          st.status = 'error'; st.error = 'no space'; cb({ status: 'error' }); return;
        }
        ls('ota.ready', B.version);
        ls('ota.readyNotes', JSON.stringify(B.notes || []));
        st.status = 'ready';
        cb({ status: 'ready', version: B.version, notes: B.notes || [], fresh: true });
      });
    });
  }

  function readyNotes() {
    try { return JSON.parse(ls('ota.readyNotes') || '[]'); } catch (e) { return []; }
  }

  function autoCheck() {
    if (!auto()) return;
    check(function (r) {
      if (r.status === 'ready' && r.fresh && window.UI) {
        UI.toast('تحديث جديد (' + r.version + ') جاهز — هيشتغل لما تفتح التطبيق المرة الجاية', 6000);
      }
    });
  }

  /* called as soon as the app has started: this version works */
  function start() {
    ls('ota.trying', null);
    setTimeout(autoCheck, FIRST_CHECK);
    setInterval(autoCheck, EVERY);
  }

  function restart() {
    try { if (window.Player && Player.stop) Player.stop(); } catch (e) {}
    location.reload();
  }

  /* forget every downloaded version: the code inside the package runs again */
  function reset() {
    /* and do not download this same version again (a newer one is fine) */
    var v = BOOT.from === 'update' ? BOOT.running : ls('ota.ready');
    if (v) ls('ota.bad', v);
    ls('ota.bundle', null); ls('ota.ready', null); ls('ota.readyNotes', null); ls('ota.trying', null);
    restart();
  }

  /* ---------------- the "updates" item in the settings ---------------- */
  function summary() {
    var v = 'الإصدار ' + BOOT.running;
    if (ready()) return v + ' · تحديث ' + ready() + ' جاهز';
    if (st.status === 'needShell') return v + ' · تحديث كبير متاح';
    return v;
  }
  function hint() {
    if (!auto()) return 'التحديث التلقائي متوقف — اضغط للبحث عن تحديث';
    return 'بيدوّر على تحديثات لوحده كل 6 ساعات وينزّلها';
  }
  function notesText(n) { return n && n.length ? '• ' + n.join('\n• ') : ''; }

  function offerRestart(v, notes, onDone) {
    UI.confirm({
      title: 'التحديث ' + v + ' جاهز', text: notesText(notes) || 'هيشتغل بعد إعادة تشغيل التطبيق.',
      buttons: [{ label: 'إعادة تشغيل التطبيق الآن', value: 'now' }, { label: 'بعدين', value: 'later' }],
      onSelect: function (x) { if (x === 'now') restart(); else if (onDone) onDone(); }
    });
  }

  function checkNow(onDone) {
    UI.loading(true, 'بيدوّر على تحديث...');
    check(function (r) {
      UI.loading(false);
      if (r.status === 'ready') { offerRestart(r.version, r.notes, onDone); return; }
      if (r.status === 'latest') UI.toast('عندك آخر إصدار (' + BOOT.running + ')');
      else if (r.status === 'needShell') {
        UI.confirm({
          title: 'تحديث كبير متاح (' + r.version + ')',
          text: 'التحديث ده محتاج يتسطّب من اللابتوب مرة واحدة، وبعدها التحديثات ترجع تنزل لوحدها.',
          buttons: [{ label: 'تمام', value: 'ok' }], onSelect: function () { if (onDone) onDone(); }
        });
        return;
      }
      else if (r.status === 'busy') UI.toast('بيدوّر على تحديث بالفعل...');
      else UI.toast('مش قادر يوصل لسيرفر التحديثات — اتأكد من الإنترنت');
      if (onDone) onDone();
    });
  }

  function menu(onDone) {
    var items = [];
    if (ready()) items.push({ label: 'تشغيل التحديث ' + ready() + ' الآن', value: 'apply' });
    items.push({ label: 'البحث عن تحديث الآن', value: 'check' });
    items.push({ label: 'التحديث التلقائي: ' + (auto() ? 'مفعّل' : 'متوقف'), value: 'auto',
      sub: auto() ? 'اضغط للإيقاف' : 'اضغط للتفعيل' });
    if (BOOT.notes && BOOT.notes.length) items.push({ label: 'إيه الجديد في الإصدار ' + BOOT.running, value: 'notes' });
    if (BOOT.from === 'update') items.push({ label: 'الرجوع للنسخة الأصلية (' + BOOT.base + ')', value: 'reset',
      sub: 'لو التحديث فيه مشكلة' });
    UI.menu({
      title: 'التحديثات · الإصدار ' + BOOT.running, items: items,
      onSelect: function (v) {
        if (v === 'apply') restart();
        else if (v === 'check') checkNow(onDone);
        else if (v === 'auto') { setAuto(!auto()); UI.toast(auto() ? 'التحديث التلقائي مفعّل' : 'التحديث التلقائي متوقف'); if (onDone) onDone(); }
        else if (v === 'notes') {
          UI.confirm({ title: 'الجديد في الإصدار ' + BOOT.running, text: notesText(BOOT.notes),
            buttons: [{ label: 'تمام', value: 'ok' }], onSelect: function () { if (onDone) onDone(); } });
        }
        else if (v === 'reset') {
          UI.confirm({
            title: 'الرجوع للنسخة الأصلية؟', text: 'هيتشال التحديث ' + BOOT.running + ' ويرجع الإصدار ' + BOOT.base + '. بياناتك ومفضلتك مش هتتأثر.',
            buttons: [{ label: 'رجوع', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }], index: 1,
            onSelect: function (x) { if (x === 'yes') reset(); else if (onDone) onDone(); }
          });
        }
        else if (onDone) onDone();
      }
    });
  }

  return {
    start: start, check: check, menu: menu, summary: summary, hint: hint,
    running: function () { return BOOT.running; }, from: function () { return BOOT.from; },
    status: function () { return st; }, ready: ready, auto: auto
  };
})();

/* ==========================================================================
   Quran Radio (Cairo) for Samsung TV — plays on start, OK = play / pause,
   Back = exit. Saudi clock, Gregorian + Hijri date, Riyadh prayer times.
   ========================================================================== */
(function () {
  /* official live stream of misrquran.gov.eg (as used by the station's own website, Nov 2026) + a relay as a backup */
  var CAIRO = [
    'https://service.webvideocore.net/CL1olYogIrDWvwqiIKK7eCxOS4PStqG9DuEjAr2ZjZQtvS3d4y9r0cvRhvS17SGN/a_7a4vuubc6mo8.m3u8',
    'http://stream.radiojar.com/8s5u5tpdtwzuv'
  ];
  /* the stations: Egypt (the main one) and Saudi Arabia - the choice is remembered */
  var STATIONS = [
    { id: 'cairo', chip: 'مصر', from: 'من القاهرة', streams: CAIRO },
    { id: 'saudi', chip: 'السعودية', from: 'من المملكة العربية السعودية', streams: [
      /* official live stream of the Saudi Broadcasting Authority (as played on radioplus.sba.sa, Nov 2026) + a relay as a backup */
      'https://live.kwikmotion.com/sbrksaquranradiolive/ksaquranradio/playlist.m3u8',
      'https://stream.radiojar.com/0tpy1h0kxtzuv'
    ] }
  ];
  var station = STATIONS[0];
  try { for (var si = 0; si < STATIONS.length; si++) if (STATIONS[si].id === localStorage.getItem('radio.station')) station = STATIONS[si]; } catch (e) {}
  var STREAMS = station.streams;
  var CITY = 'riyadh';
  var PLAY = '<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';
  var PAUSE = '<svg viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>';

  var audio, av = null, wantPlay = false, streamIdx = 0, retryTimer = null, lastMin = -1, nextPrayer = null, token = 0;
  function $(id) { return document.getElementById(id); }
  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  /* ---------------- radio ---------------- */
  function setState(kind) {
    var playing = kind === 'playing';
    $('btn').innerHTML = wantPlay ? PAUSE : PLAY;
    $('player').className = 'player' + (playing ? ' playing' : '');
    $('live').className = 'live' + (playing ? '' : ' off');
    $('live').innerHTML = playing ? 'على الهواء' : (wantPlay ? 'جاري الاتصال' : 'متوقف');
    $('state').innerHTML = kind === 'error' ? 'تعذّر الاتصال، جاري المحاولة مرة أخرى...' : '';
  }

  /* Samsung TV: AVPlay (plays HLS and MP3 streams); PC browser: <audio> */
  function start() {
    clearTimeout(retryTimer);
    wantPlay = true;
    setState('loading');
    var url = STREAMS[streamIdx];
    if (av) { avStart(url); return; }
    audio.src = url.indexOf('.m3u8') > 0 ? url : url + '?t=' + new Date().getTime();
    var p = audio.play();
    if (p && p['catch']) p['catch'](function () {});
  }

  function avStart(url) {
    var my = ++token;
    try { av.stop(); av.close(); } catch (e) {}
    try {
      av.open(url);
      av.setListener({
        onbufferingstart: function () { if (my === token) setState('loading'); },
        onbufferingprogress: function () {},
        onbufferingcomplete: function () { if (my === token) setState('playing'); },
        oncurrentplaytime: function () { if (my === token && $('live').className.indexOf('off') >= 0) setState('playing'); },
        onstreamcompleted: function () { if (my === token) retry(); },
        onerror: function () { if (my === token) retry(); },
        onevent: function () {}
      });
      av.prepareAsync(function () {
        if (my !== token) return;
        try { av.play(); setState('playing'); } catch (e) { retry(); }
      }, function () { if (my === token) retry(); });
    } catch (e) { retry(); }
  }

  function stop() {
    clearTimeout(retryTimer);
    wantPlay = false;
    token++;
    if (av) { try { av.stop(); av.close(); } catch (e) {} }
    else {
      audio.pause();
      audio.removeAttribute('src');
      try { audio.load(); } catch (e) {}
    }
    setState('stopped');
  }

  function retry() {
    if (!wantPlay) return;
    setState('error');
    clearTimeout(retryTimer);
    streamIdx = (streamIdx + 1) % STREAMS.length;
    retryTimer = setTimeout(start, 3000);
  }

  /* ---------------- clock, dates, prayer times ---------------- */
  function tick() {
    var d = SaudiTime.now();
    var min = d.getUTCHours() * 60 + d.getUTCMinutes();
    if (min !== lastMin) {
      lastMin = min;
      var p = SaudiTime.parts12(d);
      $('clock').innerHTML = p.time;
      $('ampm').innerHTML = p.ampm;
      $('date').innerHTML = esc(SaudiTime.gregorian(d));
      $('hijri').innerHTML = esc(SaudiTime.hijriText(d));
      renderPrayer();
    }
    updateCountdown();
  }

  function renderPrayer() {
    var nx = Prayer.next(CITY);
    nextPrayer = nx;
    var list = nx.today.list;
    $('city').innerHTML = 'مواقيت الصلاة · ' + esc(nx.today.city.name);
    var h = '<div class="pr-nx"><small>' + esc(nx.name) + ' بعد</small><b id="count" dir="ltr"></b></div>';
    for (var i = 0; i < list.length; i++) {
      var it = list[i];
      var isNext = nx.tomorrow ? it.key === 'fajr' : it.key === nx.key;
      var cls = 'pr-it' + (isNext ? ' next' : '') + (!nx.tomorrow && !isNext && it.minutes <= lastMin ? ' past' : '');
      h += '<div class="' + cls + '"><small>' + esc(it.name) + '</small><b>' + esc(it.text) + '</b></div>';
    }
    $('prayer').innerHTML = h;
  }

  function updateCountdown() {
    var el = $('count');
    if (!el || !nextPrayer) return;
    var d = SaudiTime.now();
    var nowSec = d.getUTCHours() * 3600 + d.getUTCMinutes() * 60 + d.getUTCSeconds();
    var nx = nextPrayer, mins = 0, l = nx.today.list;
    if (nx.tomorrow) mins = l[0].minutes + 1440;
    else for (var i = 0; i < l.length; i++) if (l[i].key === nx.key) mins = l[i].minutes;
    var left = Math.max(0, mins * 60 - nowSec);
    el.innerHTML = Math.floor(left / 3600) + ':' + pad(Math.floor((left % 3600) / 60)) + ':' + pad(left % 60);
    if (left === 0) lastMin = -1;
  }

  /* ---------------- choice of station ---------------- */
  function renderStation() {
    var h = '';
    for (var i = 0; i < STATIONS.length; i++) {
      h += '<span class="st' + (STATIONS[i] === station ? ' cur' : '') + '" data-st="' + i + '">' + STATIONS[i].chip + '</span>';
    }
    $('stations').innerHTML = h;
    var f = document.querySelectorAll('.from');
    for (var j = 0; j < f.length; j++) f[j].innerHTML = station.from;
  }
  function setStation(i) {
    i = (i + STATIONS.length) % STATIONS.length;
    if (STATIONS[i] === station) return;
    station = STATIONS[i];
    STREAMS = station.streams;
    streamIdx = 0;
    try { localStorage.setItem('radio.station', station.id); } catch (e) {}
    renderStation();
    toast('إذاعة القرآن الكريم ' + station.from);
    if (wantPlay) start();
  }

  /* ---------------- small message at the bottom (the updater uses it too) ---------------- */
  var toastTimer = null;
  function toast(msg, ms) {
    var t = $('toast');
    if (!t) return;
    t.innerHTML = esc(msg);
    t.className = 'show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.className = ''; }, ms || 3500);
  }
  window.UI = window.UI || { toast: toast };

  /* ---------------- updates (from the internet, see js/ota.js) ---------------- */
  function checkUpdate() {
    if (!window.OTA) return;
    toast('بيدوّر على تحديث...');
    OTA.check(function (r) {
      if (r.status === 'ready') {
        toast('تحديث ' + r.version + ' — جاري التشغيل...');
        setTimeout(function () { location.reload(); }, 1500);
      }
      else if (r.status === 'latest') toast('عندك آخر إصدار (' + OTA.running() + ')');
      else if (r.status === 'needShell') toast('تحديث كبير متاح — محتاج يتسطّب من اللابتوب');
      else if (r.status === 'busy') toast('بيدوّر على تحديث بالفعل...');
      else toast('مش قادر يوصل لسيرفر التحديثات — اتأكد من الإنترنت');
    });
  }

  /* ---------------- keys ---------------- */
  function onKey(e) {
    var c = e.keyCode;
    if (c === 37 || c === 39) { e.preventDefault(); setStation(STATIONS.indexOf(station) + (c === 37 ? 1 : -1)); return; }
    if (c === 38) { e.preventDefault(); checkUpdate(); return; }
    if (c === 13 || c === 10252 || c === 32) { if (wantPlay) stop(); else start(); e.preventDefault(); }
    else if (c === 415) { if (!wantPlay) start(); }
    else if (c === 19 || c === 413) { if (wantPlay) stop(); }
    else if (c === 10009 || c === 27 || c === 8) {
      e.preventDefault();
      stop();
      try { tizen.application.getCurrentApplication().exit(); } catch (err) {}
    }
  }

  function fit() {
    var s = Math.min(window.innerWidth / 1920, window.innerHeight / 1080);
    var t = s > 0 && Math.abs(s - 1) > 0.01 ? 'scale(' + s + ')' : '';
    $('app').style.transform = t; $('app').style.webkitTransform = t;
  }

  window.onload = function () {
    if (window.OTA) OTA.start();   /* this version started: keep it, look for updates later */
    renderStation();
    $('stations').addEventListener('click', function (e) {
      var i = e.target && e.target.getAttribute ? e.target.getAttribute('data-st') : null;
      if (i !== null) { e.stopPropagation(); setStation(parseInt(i, 10)); }
    });
    $('ver').innerHTML = 'الإصدار ' + (window.OTA ? OTA.running() : '');
    $('ver').addEventListener('click', checkUpdate);
    fit();
    window.addEventListener('resize', fit);
    try { tizen.tvinputdevice.registerKeyBatch(['MediaPlayPause', 'MediaPlay', 'MediaPause', 'MediaStop']); } catch (e) {}
    audio = $('audio');
    if (window.webapis && webapis.avplay) av = webapis.avplay;
    audio.addEventListener('playing', function () { setState('playing'); });
    audio.addEventListener('waiting', function () { if (wantPlay) setState('loading'); });
    audio.addEventListener('error', retry);
    audio.addEventListener('ended', retry);
    audio.addEventListener('stalled', function () { if (wantPlay) { clearTimeout(retryTimer); retryTimer = setTimeout(function () { if (wantPlay && audio.paused) retry(); }, 8000); } });
    document.addEventListener('keydown', onKey);
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) { if (wantPlay) { stop(); wantPlay = true; } }
      else if (wantPlay) start();
    });
    tick();
    setInterval(tick, 1000);
    start();
  };
  /* the updater's loader checks this to know the code started */
  window.RadioApp = { station: function () { return station.id; } };
})();

/* ==========================================================================
   events-card.js — "upcoming exhibitions & conferences in Saudi Arabia" card.
   Shows the next events from window.EVENTS (js/events.js), one at a time,
   switching every 7 seconds. Past events drop out by themselves.
   ========================================================================== */
(function () {
  var MAX = 5, EVERY = 7000;
  var MONTHS = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
  var list = [], idx = 0, dayKey = '', timer = null;

  function $(id) { return document.getElementById(id); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
  function parse(s) { var p = String(s).split('-'); return Date.UTC(+p[0], +p[1] - 1, +p[2]); }

  /* today's date in Riyadh as a UTC midnight timestamp */
  function today() {
    var d = window.SaudiTime ? SaudiTime.now() : new Date(new Date().getTime() + 3 * 3600000);
    return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
  }

  function dateRange(s, e) {
    var a = new Date(parse(s)), b = new Date(parse(e || s));
    var d1 = a.getUTCDate(), m1 = a.getUTCMonth(), y1 = a.getUTCFullYear();
    var d2 = b.getUTCDate(), m2 = b.getUTCMonth(), y2 = b.getUTCFullYear();
    if (y1 === y2 && m1 === m2) return d1 === d2 ? d1 + ' ' + MONTHS[m1] + ' ' + y1 : d1 + ' – ' + d2 + ' ' + MONTHS[m1] + ' ' + y1;
    if (y1 === y2) return d1 + ' ' + MONTHS[m1] + ' – ' + d2 + ' ' + MONTHS[m2] + ' ' + y1;
    return d1 + ' ' + MONTHS[m1] + ' ' + y1 + ' – ' + d2 + ' ' + MONTHS[m2] + ' ' + y2;
  }

  function countdown(ev, now) {
    var start = parse(ev.start), end = parse(ev.end || ev.start);
    if (now >= start && now <= end) return { text: 'جارٍ الآن', live: true };
    var n = Math.round((start - now) / 86400000);
    if (n === 1) return { text: 'غداً' };
    if (n === 2) return { text: 'بعد يومين' };
    if (n <= 10) return { text: 'بعد ' + n + ' أيام' };
    return { text: 'بعد ' + n + ' يوماً' };
  }

  function refresh() {
    var now = today(), key = String(now);
    if (key === dayKey) return;
    dayKey = key;
    var all = (window.EVENTS || []).slice(0);
    list = [];
    for (var i = 0; i < all.length; i++) if (parse(all[i].end || all[i].start) >= now) list.push(all[i]);
    list.sort(function (a, b) { return parse(a.start) - parse(b.start); });
    list = list.slice(0, MAX);
    idx = 0;
    $('events').style.display = list.length ? '' : 'none';
    render(false);
  }

  function render(animate) {
    if (!list.length) return;
    var ev = list[idx % list.length], cd = countdown(ev, today());
    var tag = ev.tag === 'work' ? '<span class="ev-tag">نشارك فيه</span>' : ev.tag === 'target' ? '<span class="ev-tag">مستهدف</span>' : '';
    var dots = '';
    for (var i = 0; i < list.length; i++) dots += '<i' + (i === idx % list.length ? ' class="on"' : '') + '></i>';
    var html =
      '<div class="ev-name">' + esc(ev.ar) + '</div>' +
      '<div class="ev-place"><b>' + esc(ev.city) + '</b>' + (ev.venue ? ' · ' + esc(ev.venue) : '') + '</div>' +
      '<div class="ev-date">' + esc(dateRange(ev.start, ev.end)) + '</div>' +
      '<div class="ev-row"><span class="ev-count' + (cd.live ? ' live' : '') + '">' + esc(cd.text) + '</span>' + tag + '</div>';
    var body = $('ev-body');
    $('ev-dots').innerHTML = dots;
    if (!animate) { body.innerHTML = html; body.className = 'ev-body'; return; }
    body.className = 'ev-body out';
    setTimeout(function () { body.innerHTML = html; body.className = 'ev-body'; }, 450);
  }

  function next() { if (list.length > 1) { idx = (idx + 1) % list.length; render(true); } }

  function start() {
    if (!$('events')) return;
    refresh();
    clearInterval(timer);
    timer = setInterval(function () { refresh(); next(); }, EVERY);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
